const response = $input.first().json;
// Posiflora возвращает токен — уточни структуру по документации
const token = response.token || response.data?.token || response.access_token;
if (!token) throw new Error('Не удалось получить токен Posiflora: ' + JSON.stringify(response));
return [{ json: { token } }];

// Получаем заказы из Posiflora
const posifloraResponse = $('Posiflora — GET /orders').first().json;
// Уточни структуру: возможно posifloraResponse.data или posifloraResponse.orders
const orders = posifloraResponse.data || posifloraResponse.orders || posifloraResponse;
const ordersArray = Array.isArray(orders) ? orders : [];

// Получаем строки из Google Sheets
const sheetRows = $input.all().map(r => r.json);

// Находим изменения статуса
const changes = [];

for (const order of ordersArray) {
  // Уточни поля по документации Posiflora:
  // order.id или order.orderid — идентификатор заказа
  // order.status — текущий статус
  const orderId = String(order.id || order.orderid || '');
  const newStatus = String(order.status || order.state || '');

  if (!orderId || !newStatus) continue;

  // Ищем этот заказ в Sheets
  const sheetRow = sheetRows.find(r => String(r.orderid || '') === orderId);
  if (!sheetRow) continue;

  // Есть chat_id — клиент зарегистрирован в боте?
  const chatId = sheetRow.chat_id;
  if (!chatId) continue;

  // Статус изменился?
  const oldStatus = sheetRow.status || '';
  if (newStatus === oldStatus) continue;

  changes.push({
    orderId,
    chatId,
    oldStatus,
    newStatus,
    clientName: sheetRow.Name || '',
    phone: sheetRow.Phone || ''
  });
}

if (changes.length === 0) {
  return [{ json: { hasChanges: false } }];
}

// Возвращаем каждое изменение отдельным item
return changes.map(c => ({ json: { hasChanges: true, ...c } }));

// Человекочитаемые названия статусов Posiflora
// Уточни реальные статусы из документации и адаптируй
const statusLabels = {
  'new': '🆕 Новый',
  'confirmed': '✅ Подтверждён',
  'in_work': '🌸 В работе (собираем букет)',
  'ready': '📦 Готов к выдаче',
  'delivery': '🚗 Передан в доставку',
  'delivered': '✅ Доставлен',
  'cancelled': '❌ Отменён',
  'completed': '🎉 Выполнен'
};

const item = $input.first().json;
const label = statusLabels[item.newStatus] || item.newStatus;

return [{ json: { ...item, statusLabel: label } }];
